"""File > New effect from a shader...: a Shadertoy shader pasted (or read
from a file) and made into a code effect of the project by native/glsl.py -
written, opened in the code pane and built, like a code effect written by
hand. What the translator cannot take is said in the window, with its line.

    shader_ui.build(app)     # the window, once (chrome.build_dialogs)
    shader_ui.show(app)      # the menu's way in
    shader_ui.make(app)      # its button: the effect made, opened, built
"""
# AI: below section was generated by an AI
import os

import dearpygui.dearpygui as dpg

from native import glsl
from native.typeface import px
from native import typeface

TAG = "shader_dialog"
EXTS = (".glsl", ".frag", ".fs", ".shader", ".txt")
EXAMPLE = """// a Shadertoy image shader: paste one here (Shadertoy's "Image" tab), or Open a file
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));
    fragColor = vec4(col,1.0);
}
"""


def _c():
    from native import chrome
    return chrome


def build(app):
    c = _c()
    with dpg.window(tag=TAG, label="New effect from a shader", no_title_bar=True, show=False, width=px(640),
                    height=px(560), no_collapse=True):
        c.dialog_header(TAG, "New effect from a shader")
        dpg.add_text("A Shadertoy image shader - mainImage(out vec4 fragColor, in vec2 fragCoord), with iTime, "
                     "iResolution, iFrame and iMouse - becomes a code effect: every LED runs it at its own place, "
                     "Speed scales iTime and Intensity is the brightness. Textures and buffers (iChannel) have "
                     "nothing to read on an LED and are refused. A device runs it in floats, pixel by pixel: a "
                     "heavy shader is slow there.", color=c.DIM, wrap=px(610))
        with dpg.group(horizontal=True):
            typeface.label(dpg.add_text("NAME", color=c.ACCENT))
            dpg.add_input_text(tag="shader_name", width=px(300), default_value="Shader", hint="the effect's name")
            dpg.add_button(label="Open a file...", tag="shader_open", callback=lambda: dpg.show_item("shader_file_dialog"))
            c.tip("a .glsl, .frag or .txt file with the shader in it, into the box")
        typeface.mono(dpg.add_input_text(tag="shader_src", multiline=True, width=-1, height=-px(70),
                                         default_value=EXAMPLE, tab_input=True))
        with dpg.group(horizontal=True):
            b = dpg.add_button(label="Make the effect", tag="shader_make", callback=lambda: make(app))
            from native import weight
            weight.primary(b)
            c.tip("the shader translated into a code effect of this project, opened in the code pane and built")
            dpg.add_text("", tag="shader_msg", color=c.DIM, wrap=px(470))
    with dpg.file_dialog(directory_selector=False, show=False, tag="shader_file_dialog", width=px(620), height=px(420),
                         callback=lambda s, a: _read_file(app, a.get("file_path_name", ""))):
        dpg.add_file_extension("{" + ",".join(EXTS) + "}", color=(120, 200, 120))
        dpg.add_file_extension(".*")


def show(app):
    _c()._centre(TAG, 640, 560)
    dpg.set_value("shader_msg", "")
    dpg.show_item(TAG)
    dpg.focus_item(TAG)


def _read_file(app, path):
    if not path:
        return
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            text = f.read(400_000)
    except OSError as e:
        dpg.set_value("shader_msg", f"could not read it: {e}"); return
    dpg.set_value("shader_src", text)
    stem = os.path.splitext(os.path.basename(path))[0].replace("_", " ").replace("-", " ").strip()
    if stem:
        dpg.set_value("shader_name", stem.title())
    dpg.set_value("shader_msg", f"{os.path.basename(path)} read: Make the effect")


def make(app, title=None, src=None):
    """The shader in the box as a new code effect: translated, written, opened and built. The file's name, or
    None with the reason in the window."""
    title = (title if title is not None else dpg.get_value("shader_name") or "").strip() or "Shader"
    src = src if src is not None else dpg.get_value("shader_src") or ""
    from native.project import _ident
    stem = _ident(title) or "shader"
    fname, n = stem + ".cpp", 2
    while os.path.exists(app.project.effect_path(fname)):
        fname = f"{stem}_{n}.cpp"; n += 1
    shown = title if fname == stem + ".cpp" else f"{title} {n - 1}"      # a second of the same name: told apart
    try:
        cpp = glsl.translate(src, shown, ident=fname[:-4])
    except glsl.ShaderError as e:
        msg = f"not made: {e}"
        if dpg.does_item_exist("shader_msg"):
            dpg.set_value("shader_msg", msg)
        app.gp.status(msg, "warn")
        return None
    app.project.write_effect(fname, cpp)
    if dpg.does_item_exist(TAG):
        dpg.hide_item(TAG)
    app.open_code(fname)
    app.gp.status(f"{shown}: made from the shader as {fname} - building")
    return fname
# AI: end
